def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full rows/columns act as dividing lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_bands, start = [], 0
    for r in sep_rows + [h]:
        if start < r:
            row_bands.append((start, r))
        start = r + 1

    col_bands, start = [], 0
    for c in sep_cols + [w]:
        if start < c:
            col_bands.append((start, c))
        start = c + 1

    if not row_bands or not col_bands:
        return grid

    rh = min(b - a for a, b in row_bands)
    cw = min(b - a for a, b in col_bands)

    # The background is the most frequent color outside the dividing lines.
    cells = [grid[r][c] for a, b in row_bands for r in range(a, b)
             for x, y in col_bands for c in range(x, y)]
    background = max(set(cells), key=cells.count)

    result = [row[:] for row in grid]
    for a, b in row_bands:
        for r in range(a, b):
            for x, y in col_bands:
                for c in range(x, y):
                    vals = [grid[rr][cc]
                            for aa, bb in row_bands for rr in range(aa, bb)
                            if (rr - aa) % rh == (r - a) % rh
                            for xx, yy in col_bands for cc in range(xx, yy)
                            if (cc - xx) % cw == (c - x) % cw
                            and grid[rr][cc] != background]
                    if vals:
                        result[r][c] = max(set(vals), key=vals.count)
    return result
