def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the field/background, not a divider.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    sep_rows = [r for r, row in enumerate(grid)
                if row[0] != bg and all(v == row[0] for v in row)]
    sep_cols = [c for c in range(w)
                if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))]

    def make_bands(size, separators):
        bands, start = [], 0
        for p in separators + [size]:
            if start < p:
                bands.append((start, p))
            start = p + 1
        return bands

    rb = make_bands(h, sep_rows)
    cb = make_bands(w, sep_cols)
    if not rb or not cb:
        return grid

    panels = [(a, b, x, y) for a, b in rb for x, y in cb]
    # Use the panel containing the most non-background cells as the motif.
    a, b, x, y = max(
        panels,
        key=lambda p: sum(grid[r][c] != bg
                          for r in range(p[0], p[1])
                          for c in range(p[2], p[3]))
    )
    motif = [row[x:y] for row in grid[a:b]]
    mh, mw = len(motif), len(motif[0])

    out = [row[:] for row in grid]
    for ra, rb_ in rb:
        for ca, cb_ in cb:
            for r in range(ra, rb_):
                for c in range(ca, cb_):
                    out[r][c] = motif[(r - ra) % mh][(c - ca) % mw]
    return out
